  ('cf275895-bb2a-5bab-bcb5-c5b679573dc2'::uuid,1,'If we had no limits for one night—no time constraints, no place off-limits—what would we do?','if we had no limits for one night no time constraints no place off limits what would we do','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('01978636-c336-58a8-a8a8-428d323a9304'::uuid,1,'Would you enjoy it if your partner flirted with you at a party as though you were strangers?','would you enjoy it if your partner flirted with you at a party as though you were strangers','{}'::jsonb,'published','Initial deterministic bundled-content import'),
