do $$ begin if (select count(*) from public.content_item_categories m join public.content_items i on i.id=m.item_id where m.enabled and i.lifecycle_status='active' and i.published_version is not null and i.game_id in ('truth-or-dare','spicy-starters','never-have-i-ever','late-night-talks','dinner-table','icebreaker','everyday-conversation','reconnect','red-flag-green-flag','charades','strangers','finger-down','take-a-sip','sip-or-spill','you-laugh','do-or-drink','most-likely-to','choose-your-side','who-said-that','we-just-met','imposter','mini-mystery','do-you-know-me','think-fast','not-me-your-honour','bad-advice-only')) < 12712 then raise exception 'Content seed reconciliation failed: expected at least 12712 active published memberships'; end if; end $$;
